"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[685],{2572(n,e,a){a.r(e),a.d(e,{assets:()=>d,contentTitle:()=>l,default:()=>h,frontMatter:()=>c,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"part3-agent-protocols/a2a-protocol","title":"A2A 1.0: Agent Discovery, Delegation, and Long-Running Tasks","description":"The previous chapters used MCP to expose tools and context to an AI host. A2A addresses the next boundary: one autonomous agent delegates work to another autonomous agent without depending on the other agent\'s interna...","source":"@site/docs/part3-agent-protocols/05-a2a-protocol.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/05-a2a-protocol","permalink":"/tutorials/part3-agent-protocols/05-a2a-protocol","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":5,"frontMatter":{"title":"A2A 1.0: Agent Discovery, Delegation, and Long-Running Tasks","slug":"/part3-agent-protocols/05-a2a-protocol","description":"The previous chapters used MCP to expose tools and context to an AI host. A2A addresses the next boundary: one autonomous agent delegates work to another autonomous agent without depending on the other agent\'s interna...","sidebar_label":"5. A2A protocol 1.0","pagination_label":"5. A2A protocol 1.0","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"4. MCP protocol evolution","permalink":"/tutorials/part3-agent-protocols/04-mcp-2025-update"},"next":{"title":"6. JavaScript and TypeScript primer","permalink":"/tutorials/part3-agent-protocols/06-javascript-typescript-primer"}}');var t=a(4848),o=a(8453),r=a(8172);const i=JSON.parse('{"sourcePath":"part3-agent-protocols/05-a2a-protocol.html","route":"/part3-agent-protocols/05-a2a-protocol","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"A2A 1.0: Agent Discovery, Delegation, and Long-Running Tasks","title":"A2A 1.0: Agent Discovery, Delegation, and Long-Running Tasks","description":"The previous chapters used MCP to expose tools and context to an AI host. A2A addresses the next boundary: one autonomous agent delegates work to another autonomous agent without depending on the other agent\'s interna...","readingMinutes":17,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-a2a-is-the-mental-model","label":"1) What A2A is (the mental model)"},{"id":"2-why-a2a-exists-problems-it-solves","label":"2) Why A2A exists (problems it solves)"},{"id":"3-core-concepts-and-vocabulary","label":"3) Core concepts and vocabulary"},{"id":"4-agent-discovery-via-agentcard","label":"4) Agent discovery via AgentCard"},{"id":"5-skills-how-agents-advertise-capability","label":"5) Skills: how agents advertise capability"},{"id":"6-tasks-status-and-long-running-work","label":"6) Tasks, status, and long-running work"},{"id":"7-messages-parts-and-artifacts","label":"7) Messages, parts, and artifacts"},{"id":"8-interaction-models-sync-vs-streaming-vs-async","label":"8) Interaction models: sync vs streaming vs async"},{"id":"9-orchestration-patterns","label":"9) Orchestration patterns"},{"id":"10-concrete-scenario-purchasing-concierge-inventory-approval","label":"10) Concrete scenario: Purchasing Concierge + Inventory + Approval"},{"id":"11-a2a-1-0-wire-examples-agent-card-and-task-lifecycle","label":"11) A2A 1.0 wire examples: Agent Card and task lifecycle"},{"id":"12-security-and-authorization-boundaries","label":"12) Security and authorization boundaries"},{"id":"13-mechanics-first-python-simulator-server-concierge-client","label":"13) Mechanics-first Python simulator (server + concierge client)"},{"id":"14-operational-checklist-retries-idempotency-observability","label":"14) Operational checklist (retries, idempotency, observability)"},{"id":"summary-the-complete-mental-model","label":"Summary: the complete mental model"},{"id":"official-reference","label":"Official reference"}],"html":"<div class=\\"ch\\">\\n    \\n    <p>\\n      The previous chapters used MCP to expose tools and context to an AI host.\\n      A2A addresses the next boundary: one autonomous agent delegates work to\\n      another autonomous agent without depending on the other agent\'s internal\\n      framework, memory, model, or tools. We will build the idea from a simple\\n      message into discovery, task state, multi-turn input, artifacts,\\n      streaming, security, and a purchasing-concierge implementation.\\n    </p>\\n\\n    <div class=\\"toc\\">\\n      <strong>Contents</strong>\\n      <ul>\\n        <li><a href=\\"#intro\\">1) What A2A is (the mental model)</a></li>\\n        <li><a href=\\"#why\\">2) Why A2A exists (problems it solves)</a></li>\\n        <li><a href=\\"#concepts\\">3) Core concepts and vocabulary</a></li>\\n        <li><a href=\\"#agentcard\\">4) Agent discovery via AgentCard</a></li>\\n        <li><a href=\\"#skills\\">5) Skills: how agents advertise capability</a></li>\\n        <li><a href=\\"#tasks\\">6) Tasks, status, and long-running work</a></li>\\n        <li><a href=\\"#messages\\">7) Messages, parts, and artifacts</a></li>\\n        <li><a href=\\"#interaction\\">8) Interaction models: sync vs streaming vs async</a></li>\\n        <li><a href=\\"#orchestration\\">9) Orchestration patterns (concierge, hub, mesh)</a></li>\\n        <li><a href=\\"#example\\">10) A full concrete scenario: Purchasing Concierge + Inventory + Approval</a></li>\\n        <li><a href=\\"#json\\">11) Practical JSON examples (AgentCard + task lifecycle)</a></li>\\n        <li><a href=\\"#security\\">12) Security and authentication (what you must implement)</a></li>\\n        <li><a href=\\"#python\\">13) Minimal Python implementation (server + concierge client)</a></li>\\n        <li><a href=\\"#operational\\">14) Operational checklist (retries, idempotency, observability)</a></li>\\n      </ul>\\n    </div>\\n\\n  <section id=\\"intro\\">\\n    <h2 id=\\"1-what-a2a-is-the-mental-model\\">1) What A2A is (the mental model)</h2>\\n\\n    <p>\\n      A2A is a standard way for <strong>agents</strong>, rather than only tools,\\n      to communicate with each other over a network.\\n      The important word is \u201cagents\u201d: each participant is allowed to be autonomous, stateful, long-running,\\n      and potentially opaque internally. A2A does not require agents to share their chain-of-thought, private memory,\\n      or internal tools. Instead, they collaborate via a shared external protocol.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        An agent wants help \u2192 it finds another agent \u2192 it delegates work as a Task\\n        \u2192 it receives Messages and Artifacts \u2192 it continues / completes the Task.\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>One-line mental model:</strong> A2A is structured messages,\\n      discoverable capabilities, and a durable task lifecycle for collaboration\\n      across vendors, frameworks, and deployments.\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Version used in this chapter</strong>\\n      The normative examples target stable A2A <code>1.0</code>. The protocol\\n      defines one canonical data model and three standard bindings:\\n      <code>JSONRPC</code>, <code>GRPC</code>, and\\n      <code>HTTP+JSON</code>. The HTTP+JSON examples send\\n      <code>A2A-Version: 1.0</code> and use\\n      <code>application/a2a+json</code>.\\n    </div>\\n\\n    <figure class=\\"figure-card\\">\\n      <svg viewBox=\\"0 0 1040 390\\" role=\\"img\\" aria-labelledby=\\"a2a-model-title a2a-model-desc\\">\\n        <title id=\\"a2a-model-title\\">A2A delegation model</title>\\n        <desc id=\\"a2a-model-desc\\">A concierge discovers two specialist agents, delegates tasks, receives status updates, and combines artifacts.</desc>\\n        <defs>\\n          <marker id=\\"a2a-blue-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n          </marker>\\n          <marker id=\\"a2a-green-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#14875a\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <rect x=\\"40\\" y=\\"135\\" width=\\"180\\" height=\\"110\\" rx=\\"16\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"130\\" y=\\"177\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Concierge</text>\\n        <text x=\\"130\\" y=\\"207\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">owns user journey</text>\\n\\n        <rect x=\\"430\\" y=\\"55\\" width=\\"220\\" height=\\"110\\" rx=\\"16\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"540\\" y=\\"97\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Inventory agent</text>\\n        <text x=\\"540\\" y=\\"127\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">stock + quote artifact</text>\\n\\n        <rect x=\\"430\\" y=\\"230\\" width=\\"220\\" height=\\"110\\" rx=\\"16\\" fill=\\"#fff4e5\\" stroke=\\"#d78b00\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"540\\" y=\\"272\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Approval agent</text>\\n        <text x=\\"540\\" y=\\"302\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">input + decision artifact</text>\\n\\n        <rect x=\\"820\\" y=\\"135\\" width=\\"180\\" height=\\"110\\" rx=\\"16\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n        <text x=\\"910\\" y=\\"177\\" text-anchor=\\"middle\\" font-size=\\"18\\" font-weight=\\"700\\" fill=\\"#162033\\">Final plan</text>\\n        <text x=\\"910\\" y=\\"207\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">composed artifacts</text>\\n\\n        <path d=\\"M220,166 C300,166 330,110 430,110\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#a2a-blue-arrow)\\"></path>\\n        <path d=\\"M220,214 C300,214 330,285 430,285\\" fill=\\"none\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#a2a-blue-arrow)\\"></path>\\n        <path d=\\"M650,110 C735,110 745,166 820,166\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#a2a-green-arrow)\\"></path>\\n        <path d=\\"M650,285 C735,285 745,214 820,214\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#a2a-green-arrow)\\"></path>\\n\\n        <text x=\\"322\\" y=\\"89\\" text-anchor=\\"middle\\" font-size=\\"14\\" font-weight=\\"700\\" fill=\\"#1769e0\\">message + task</text>\\n        <text x=\\"322\\" y=\\"313\\" text-anchor=\\"middle\\" font-size=\\"14\\" font-weight=\\"700\\" fill=\\"#1769e0\\">message + task</text>\\n        <text x=\\"732\\" y=\\"89\\" text-anchor=\\"middle\\" font-size=\\"14\\" font-weight=\\"700\\" fill=\\"#14875a\\">status + artifact</text>\\n        <text x=\\"732\\" y=\\"313\\" text-anchor=\\"middle\\" font-size=\\"14\\" font-weight=\\"700\\" fill=\\"#14875a\\">status + artifact</text>\\n      </svg>\\n      <figcaption>\\n        The delegating agent does not need the specialists\' private reasoning;\\n        it needs trustworthy discovery metadata and explicit task outputs.\\n      </figcaption>\\n    </figure>\\n  </section>\\n\\n  <section id=\\"why\\">\\n    <h2 id=\\"2-why-a2a-exists-problems-it-solves\\">2) Why A2A exists (problems it solves)</h2>\\n\\n    <div class=\\"cols\\">\\n      <div class=\\"card\\">\\n        <strong>Problem 1: Agents live in silos</strong>\\n        <p class=\\"muted\\">\\n          One team builds an agent with Framework A, another team builds a specialist agent with Framework B,\\n          a third vendor provides a hosted agent. Without a common \u201clanguage,\u201d collaboration becomes bespoke glue code.\\n        </p>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Problem 2: Work is long-running and multi-turn</strong>\\n        <p class=\\"muted\\">\\n          Real workflows have approvals, waiting on humans, retries, partial progress, streaming updates,\\n          and artifacts (files, forms, structured outputs).\\n        </p>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Problem 3: You need discovery</strong>\\n        <p class=\\"muted\\">\\n          If an agent is going to delegate, it must discover capabilities:\\n          \u201cWho can do inventory checks?\u201d \u201cWho can approve spending?\u201d \u201cWhat modalities do they accept?\u201d\\n        </p>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Problem 4: Enterprises need governance</strong>\\n        <p class=\\"muted\\">\\n          Identity, authentication, authorization, audit logs, versioning, and safe handling\\n          of files/URLs must be aligned with typical enterprise security practices.\\n        </p>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      A2A is not \u201ca prompt format.\u201d It\u2019s a collaboration protocol with discovery, structured data, and lifecycle.\\n    </div>\\n  </section>\\n\\n  <section id=\\"concepts\\">\\n    <h2 id=\\"3-core-concepts-and-vocabulary\\">3) Core concepts and vocabulary</h2>\\n\\n    <p>These are the A2A building blocks you should hold in your head:</p>\\n\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Concept</th>\\n          <th>Meaning</th>\\n          <th>Why it matters</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Agent</strong></td>\\n          <td>A network service that can accept tasks and return results.</td>\\n          <td>Agents are peers: each can delegate to another agent.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>AgentCard</strong></td>\\n          <td>A machine-readable \u201cbusiness card\u201d that describes an agent\'s interfaces, skills, modalities, capabilities, and security requirements.</td>\\n          <td>Enables discovery and safe routing.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Skill</strong></td>\\n          <td>A declared capability like \u201ccheck_inventory\u201d or \u201capprove_purchase\u201d.</td>\\n          <td>Used to choose the right agent for a subtask.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Task</strong></td>\\n          <td>The core unit of delegated work with an <code>id</code>, <code>contextId</code>, status, optional history, and artifacts.</td>\\n          <td>Supports long-running work and human-in-the-loop.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Message</strong></td>\\n          <td>A communication unit inside a task (request, update, clarification, final answer).</td>\\n          <td>Multi-turn interactions without leaking internal state.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Part</strong></td>\\n          <td>A piece of message or artifact content containing exactly one of text, raw bytes, a URL, or structured data.</td>\\n          <td>Enables multi-modality and structured payloads.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Artifact</strong></td>\\n          <td>An output object produced by the task (report, file, decision record, structured JSON).</td>\\n          <td>Separates \u201cconversation\u201d from \u201cdeliverables.\u201d</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Think \u201cproject management\u201d:</strong> a Task has a status, Messages\\n      are the discussion, and Artifacts are the deliverables. A\\n      <code>contextId</code> can group multiple related tasks into one\\n      continuing interaction.\\n    </div>\\n  </section>\\n\\n  <section id=\\"agentcard\\">\\n    <h2 id=\\"4-agent-discovery-via-agentcard\\">4) Agent discovery via AgentCard</h2>\\n\\n    <p>\\n      Discovery starts with the Agent Card: a JSON document published by an\\n      A2A server at a well-known path such as\\n      <code>/.well-known/agent-card.json</code>.\\n      The purpose is to make it possible for other agents (or an orchestrator) to learn:\\n    </p>\\n    <ul>\\n      <li>Who this agent is (name/version/vendor)</li>\\n      <li>Where to send requests and which bindings/versions each endpoint supports</li>\\n      <li>What the agent can do (skills)</li>\\n      <li>How to authenticate (schemes, requirements)</li>\\n      <li>What interaction styles it supports (streaming, push notifications, extended card)</li>\\n    </ul>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Concierge agent wants \u201cinventory check\u201d\\n          \u2193\\n        GET well-known AgentCard for candidate agents\\n          \u2193\\n        Choose agent whose Skills match the needed work\\n          \u2193\\n        Create Task + exchange Messages/Artifacts until complete\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Security note:</strong> even though the AgentCard is a discovery document,\\n      you should treat it as a potentially sensitive surface and protect it appropriately (don\u2019t embed secrets).\\n    </div>\\n\\n    <h3 id=\\"4-1-interface-selection-is-ordered-not-guessed\\">4.1 Interface selection is ordered, not guessed</h3>\\n    <p>\\n      A 1.0 Agent Card can list several <code>supportedInterfaces</code> in\\n      preference order. A client chooses the first binding it supports and\\n      uses that interface\'s URL and protocol version. If the interface\\n      declares an opaque <code>tenant</code> routing value, the client copies\\n      it into every request for that interface.\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr><th>Binding</th><th>Best fit</th><th>Streaming</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr><td><code>HTTP+JSON</code></td><td>REST-oriented services and browser-friendly infrastructure</td><td>Server-Sent Events</td></tr>\\n        <tr><td><code>JSONRPC</code></td><td>RPC-oriented clients over HTTP</td><td>Server-Sent Events</td></tr>\\n        <tr><td><code>GRPC</code></td><td>Strongly typed internal platforms and generated clients</td><td>gRPC server streaming</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <p>\\n      Public cards must not contain credentials. When\\n      <code>capabilities.extendedAgentCard</code> is enabled, an authenticated\\n      client can fetch a richer card after obtaining credentials out of band.\\n      Cards may also be signed with JWS after JSON Canonicalization Scheme\\n      normalization when provenance and tamper detection are required.\\n    </p>\\n  </section>\\n\\n  <section id=\\"skills\\">\\n    <h2 id=\\"5-skills-how-agents-advertise-capability\\">5) Skills: how agents advertise capability</h2>\\n\\n    <p>\\n      A2A \u201cSkills\u201d are intentionally high-level: they describe what an agent does in a way\\n      another system can reason about. Skills are not the internal tool list, not chain-of-thought,\\n      and not implementation details.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <strong>A skill typically answers:</strong>\\n      <ul>\\n        <li><strong>What</strong> the agent can do (\u201capprove_purchase\u201d, \u201cinventory_availability\u201d)</li>\\n        <li><strong>Input modes and examples</strong> that help a router understand when the skill applies</li>\\n        <li><strong>Output modes</strong> returned through artifacts</li>\\n        <li><strong>Constraints</strong> (needs human approval, requires certain auth scope)</li>\\n      </ul>\\n    </div>\\n\\n    <p>\\n      Practically, your orchestrator (concierge) uses skills like a routing index:\\n      \u201cWhich agent should I hire for this sub-problem?\u201d\\n    </p>\\n  </section>\\n\\n  <section id=\\"tasks\\">\\n    <h2 id=\\"6-tasks-status-and-long-running-work\\">6) Tasks, status, and long-running work</h2>\\n\\n    <p>\\n      A2A is \u201casync-first.\u201d That means it is designed for tasks that may take time:\\n      waiting on a human, waiting on another system, or doing multi-step reasoning.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <strong>A2A 1.0 task states:</strong>\\n      <table>\\n        <thead><tr><th>State</th><th>Meaning</th><th>Terminal?</th></tr></thead>\\n        <tbody>\\n          <tr><td><code>TASK_STATE_UNSPECIFIED</code></td><td>Unknown or indeterminate state; avoid creating tasks in this state.</td><td>No</td></tr>\\n          <tr><td><code>TASK_STATE_SUBMITTED</code></td><td>Accepted and acknowledged.</td><td>No</td></tr>\\n          <tr><td><code>TASK_STATE_WORKING</code></td><td>Actively being processed.</td><td>No</td></tr>\\n          <tr><td><code>TASK_STATE_INPUT_REQUIRED</code></td><td>More user input is required.</td><td>Interrupted</td></tr>\\n          <tr><td><code>TASK_STATE_AUTH_REQUIRED</code></td><td>Authorization must be fulfilled through an agreed mechanism.</td><td>Interrupted</td></tr>\\n          <tr><td><code>TASK_STATE_COMPLETED</code></td><td>Finished successfully; inspect artifacts for deliverables.</td><td>Yes</td></tr>\\n          <tr><td><code>TASK_STATE_FAILED</code></td><td>Finished with an error.</td><td>Yes</td></tr>\\n          <tr><td><code>TASK_STATE_CANCELED</code></td><td>Canceled before completion.</td><td>Yes</td></tr>\\n          <tr><td><code>TASK_STATE_REJECTED</code></td><td>The agent decided not to perform the task.</td><td>Yes</td></tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <p>\\n      Earlier diagrams often called these states <em>created</em>,\\n      <em>running</em>, <em>needs input</em>, <em>blocked</em>, and\\n      <em>succeeded</em>. Those remain useful plain-English descriptions, but\\n      they are not the 1.0 wire values. External-system waiting is normally\\n      represented as <code>TASK_STATE_WORKING</code> plus a status message;\\n      user clarification and authorization have their own explicit states.\\n    </p>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Why tasks exist:</strong> If agents only did one-shot request/response, they\u2019d fail on most real workflows.\\n      Tasks let agents coordinate across time, state, and dependencies.\\n    </div>\\n  </section>\\n\\n  <section id=\\"messages\\">\\n    <h2 id=\\"7-messages-parts-and-artifacts\\">7) Messages, parts, and artifacts</h2>\\n\\n    <h3 id=\\"7-1-messages\\">7.1 Messages</h3>\\n    <p>\\n      A Message is \u201cwhat we said\u201d within an interaction: a request,\\n      clarification, follow-up, or status explanation. Every Message has a\\n      creator-assigned <code>messageId</code>, a role, and at least one Part.\\n      The two wire roles are <code>ROLE_USER</code> for client-to-agent\\n      messages and <code>ROLE_AGENT</code> for agent-to-client messages.\\n      <code>contextId</code> and <code>taskId</code> associate later turns\\n      with ongoing work.\\n    </p>\\n\\n    <h3 id=\\"7-2-parts\\">7.2 Parts</h3>\\n    <p>\\n      A Part is \u201cwhat kind of content this is.\u201d A2A is modality-agnostic.\\n      A Part contains exactly one of <code>text</code>, base64-encoded\\n      <code>raw</code> bytes, a file <code>url</code>, or JSON-compatible\\n      <code>data</code>. File metadata such as filename and media type sits\\n      beside the chosen content field.\\n    </p>\\n\\n    <h3 id=\\"7-3-artifacts\\">7.3 Artifacts</h3>\\n    <p>\\n      Artifacts are the outputs: a report, a decision, a JSON payload, an attached file reference, a filled form.\\n      Every artifact has an <code>artifactId</code> unique within its task and\\n      one or more Parts. The key design win is: artifacts represent\\n      deliverables; messages represent conversation.\\n    </p>\\n\\n    <div class=\\"callout warn\\">\\n      If you mix \u201cfinal deliverables\u201d and \u201cchatty conversation\u201d into one blob of text,\\n      you make downstream automation fragile. Artifacts fix that by making outputs explicit.\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Reliability boundary</strong>\\n      A task history is not guaranteed to retain every transient Message, and\\n      a disconnected stream may miss informational updates. Put durable\\n      results in Artifacts and recover current state with task operations;\\n      do not use chat messages as a guaranteed event log.\\n    </div>\\n  </section>\\n\\n  <section id=\\"interaction\\">\\n    <h2 id=\\"8-interaction-models-sync-vs-streaming-vs-async\\">8) Interaction models: sync vs streaming vs async</h2>\\n\\n    <p>\\n      A2A supports multiple interaction modes so agents can choose what is appropriate:\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Mode</th>\\n          <th>When to use</th>\\n          <th>How it feels</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Synchronous</strong></td>\\n          <td>Fast tasks that can complete quickly.</td>\\n          <td><code>SendMessage</code> returns a direct Message or a completed Task.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Streaming</strong></td>\\n          <td>You want progress updates or partial results.</td>\\n          <td><code>SendStreamingMessage</code> emits the initial Task or Message, then status/artifact update events.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Asynchronous</strong></td>\\n          <td>Long-running tasks, human-in-loop approvals, external dependencies.</td>\\n          <td>Receive a submitted/working Task, then poll, subscribe, or configure authenticated push notifications.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"callout ok\\">\\n      A2A is built to treat \u201cwaiting\u201d as normal. That\u2019s why the task object and its status/history are central.\\n    </div>\\n\\n    <p>\\n      The binding changes the transport shape, not the meaning. For example,\\n      HTTP+JSON uses <code>POST /message:send</code>, JSON-RPC invokes\\n      <code>SendMessage</code>, and gRPC calls the generated\\n      <code>SendMessage</code> method. All three carry the same canonical\\n      request and produce functionally equivalent objects.\\n    </p>\\n  </section>\\n\\n  <section id=\\"orchestration\\">\\n    <h2 id=\\"9-orchestration-patterns\\">9) Orchestration patterns</h2>\\n\\n    <p>\\n      In multi-agent systems, there are common architectures:\\n    </p>\\n\\n    <div class=\\"cols\\">\\n      <div class=\\"card\\">\\n        <strong>Concierge (Orchestrator) Pattern</strong>\\n        <p class=\\"muted\\">\\n          One \u201cfront\u201d agent speaks to the user and hires specialist agents for subtasks.\\n          This keeps the user experience consistent and concentrates policy + governance in one place.\\n        </p>\\n        <div class=\\"diagram\\">\\n          User \u2194 Concierge\\n               \u2199     \u2198\\n          Inventory   Approval\\n        </div>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Hub-and-Spoke (Platform) Pattern</strong>\\n        <p class=\\"muted\\">\\n          A central platform routes tasks and enforces org-wide authentication, authorization,\\n          quotas, and auditing. Individual agents remain independent services.\\n        </p>\\n        <div class=\\"diagram\\">\\n          Agents \u2194 Hub \u2194 Agents\\n        </div>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Mesh (Peer-to-Peer) Pattern</strong>\\n        <p class=\\"muted\\">\\n          Agents directly discover and delegate to each other. Powerful, but harder to govern\\n          unless you add strong identity and allow-lists.\\n        </p>\\n        <div class=\\"diagram\\">\\n          Agent A \u2194 Agent B \u2194 Agent C\\n               \u2196\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2199\\n        </div>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Human-in-the-Loop Variant</strong>\\n        <p class=\\"muted\\">\\n          One or more tasks become \u201cblocked\u201d until a human approves or provides missing information.\\n          A2A\u2019s async-first model makes this a first-class concept.\\n        </p>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      If you\u2019re building your first system, start with the <strong>concierge pattern</strong>.\\n      It\u2019s easiest to debug, easiest to secure, and easiest to explain.\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"example\\">\\n    <h2 id=\\"10-concrete-scenario-purchasing-concierge-inventory-approval\\">10) Concrete scenario: Purchasing Concierge + Inventory + Approval</h2>\\n\\n    <p>\\n      Let\u2019s implement the exact \u201cwhy do we need this and what does it do?\u201d story using A2A.\\n      Your user says: <em>\u201cBuy 20 keyboards for the team.\u201d</em>\\n      The concierge agent must:\\n    </p>\\n    <ol>\\n      <li>Find an inventory agent to check stock and pricing</li>\\n      <li>Find an approval agent to approve budget (human-in-loop)</li>\\n      <li>Return a final \u201capproved purchase plan\u201d to the user</li>\\n    </ol>\\n\\n    <div class=\\"card\\">\\n      <strong>Agents (roles)</strong>\\n      <ul>\\n        <li><strong>Concierge Agent</strong>: user-facing, orchestrates subtasks</li>\\n        <li><strong>Inventory Agent</strong>: checks availability, lead time, estimated cost</li>\\n        <li><strong>Approval Agent</strong>: determines if purchase is allowed and records approval</li>\\n      </ul>\\n    </div>\\n\\n    <h3 id=\\"10-1-step-by-step-flow-exactly-what-happens\\">10.1 Step-by-step flow (exactly what happens)</h3>\\n    <div class=\\"card\\">\\n      <ol>\\n        <li><strong>Discovery:</strong> Concierge fetches AgentCards for Inventory and Approval agents.</li>\\n        <li><strong>Routing:</strong> Concierge selects agents by matching required Skills.</li>\\n        <li><strong>Delegate inventory task:</strong> Concierge creates a Task on Inventory agent: \u201cCheck 20 keyboards.\u201d</li>\\n        <li><strong>Inventory responds:</strong> Inventory produces an Artifact: availability + cost breakdown.</li>\\n        <li><strong>Delegate approval task:</strong> Concierge creates a Task on Approval agent with the cost breakdown.</li>\\n        <li><strong>Approval pauses:</strong> Approval agent returns <code>TASK_STATE_INPUT_REQUIRED</code> with a Message explaining which manager decision is needed.</li>\\n        <li><strong>Human approves:</strong> Concierge (or UI) submits approval decision back to Approval agent.</li>\\n        <li><strong>Approval completes:</strong> Approval agent transitions to <code>TASK_STATE_COMPLETED</code> and emits an approval Artifact (decision + approver + timestamp).</li>\\n        <li><strong>Concierge finalizes:</strong> Concierge returns a final plan to the user.</li>\\n      </ol>\\n    </div>\\n\\n    <div class=\\"callout ok\\">\\n      This is what A2A \u201cgives you\u201d: the structured way to discover agents, start tasks, wait safely, and collect artifacts.\\n      Without a shared protocol, each integration must invent discovery,\\n      payloads, status semantics, versioning, and long-running state.\\n    </div>\\n  </section>\\n\\n  <section id=\\"json\\">\\n    <h2 id=\\"11-a2a-1-0-wire-examples-agent-card-and-task-lifecycle\\">11) A2A 1.0 wire examples: Agent Card and task lifecycle</h2>\\n\\n    <h3 id=\\"11-1-agent-card-for-the-inventory-agent\\">11.1 Agent Card for the Inventory Agent</h3>\\n    <p>\\n      This card advertises the HTTP+JSON binding first, so it is the preferred\\n      interface. The skill is intentionally descriptive: A2A routing uses\\n      names, descriptions, tags, examples, and media modes rather than a\\n      protocol-level function-argument schema.\\n    </p>\\n\\n    <pre><code class=\\"language-json\\">// GET https://inventory.example/.well-known/agent-card.json\\n{\\n  \\"name\\": \\"Inventory Agent\\",\\n  \\"description\\": \\"Checks stock, price, and lead time for purchase requests.\\",\\n  \\"supportedInterfaces\\": [\\n    {\\n      \\"url\\": \\"https://inventory.example/a2a/v1\\",\\n      \\"protocolBinding\\": \\"HTTP+JSON\\",\\n      \\"protocolVersion\\": \\"1.0\\"\\n    },\\n    {\\n      \\"url\\": \\"inventory.example:443\\",\\n      \\"protocolBinding\\": \\"GRPC\\",\\n      \\"protocolVersion\\": \\"1.0\\"\\n    }\\n  ],\\n  \\"provider\\": {\\n    \\"organization\\": \\"Example Procurement Platform\\",\\n    \\"url\\": \\"https://inventory.example\\"\\n  },\\n  \\"version\\": \\"1.0.0\\",\\n  \\"capabilities\\": {\\n    \\"streaming\\": true,\\n    \\"pushNotifications\\": true,\\n    \\"extendedAgentCard\\": false\\n  },\\n  \\"securitySchemes\\": {\\n    \\"workloadBearer\\": {\\n      \\"httpAuthSecurityScheme\\": {\\n        \\"scheme\\": \\"Bearer\\",\\n        \\"bearerFormat\\": \\"JWT\\"\\n      }\\n    }\\n  },\\n  \\"securityRequirements\\": [\\n    {\\"schemes\\": {\\"workloadBearer\\": {\\"list\\": []}}}\\n  ],\\n  \\"defaultInputModes\\": [\\"text/plain\\", \\"application/json\\"],\\n  \\"defaultOutputModes\\": [\\"application/json\\", \\"text/plain\\"],\\n  \\"skills\\": [\\n    {\\n      \\"id\\": \\"inventory.check\\",\\n      \\"name\\": \\"Inventory Check\\",\\n      \\"description\\": \\"Returns stock, unit price, back-order lead time, and estimated total for a requested item and quantity.\\",\\n      \\"tags\\": [\\"inventory\\", \\"stock\\", \\"pricing\\", \\"procurement\\"],\\n      \\"examples\\": [\\n        \\"Check availability and price for 20 keyboards.\\",\\n        \\"{\\\\\\"item\\\\\\":\\\\\\"keyboard\\\\\\",\\\\\\"quantity\\\\\\":20}\\"\\n      ],\\n      \\"inputModes\\": [\\"text/plain\\", \\"application/json\\"],\\n      \\"outputModes\\": [\\"application/json\\"]\\n    }\\n  ]\\n}</code></pre>\\n\\n    <h3 id=\\"11-2-send-a-message-concierge-to-inventory-agent\\">11.2 Send a message (Concierge to Inventory Agent)</h3>\\n    <p>\\n      A client sends a Message; it does not directly invent a Task. The agent\\n      may return a direct response Message for trivial work or create and\\n      return a Task when lifecycle tracking is useful.\\n    </p>\\n\\n    <pre><code class=\\"language-http\\">POST /a2a/v1/message:send HTTP/1.1\\nHost: inventory.example\\nAuthorization: Bearer eyJ...\\nContent-Type: application/a2a+json\\nA2A-Version: 1.0\\n\\n{\\n  \\"message\\": {\\n    \\"messageId\\": \\"msg-7f83\\",\\n    \\"role\\": \\"ROLE_USER\\",\\n    \\"parts\\": [\\n      {\\"text\\": \\"Check availability and price for 20 keyboards.\\"},\\n      {\\"data\\": {\\"item\\": \\"keyboard\\", \\"quantity\\": 20}}\\n    ]\\n  },\\n  \\"configuration\\": {\\n    \\"acceptedOutputModes\\": [\\"application/json\\"]\\n  }\\n}</code></pre>\\n\\n    <h3 id=\\"11-3-inventory-returns-a-completed-task-and-artifact\\">11.3 Inventory returns a completed Task and Artifact</h3>\\n    <pre><code class=\\"language-json\\">{\\n  \\"task\\": {\\n    \\"id\\": \\"task_123\\",\\n    \\"contextId\\": \\"purchase_8b1\\",\\n    \\"status\\": {\\n      \\"state\\": \\"TASK_STATE_COMPLETED\\",\\n      \\"timestamp\\": \\"2026-07-30T10:20:00Z\\"\\n    },\\n    \\"artifacts\\": [\\n      {\\n        \\"artifactId\\": \\"artifact_quote_1\\",\\n        \\"name\\": \\"Inventory quote\\",\\n        \\"parts\\": [\\n          {\\n            \\"data\\": {\\n              \\"item\\": \\"keyboard\\",\\n              \\"quantity\\": 20,\\n              \\"available\\": 18,\\n              \\"backorderEtaDays\\": 7,\\n              \\"unitPrice\\": 35.0,\\n              \\"currency\\": \\"USD\\",\\n              \\"estimatedTotal\\": 700.0\\n            }\\n          }\\n        ]\\n      }\\n    ]\\n  }\\n}</code></pre>\\n\\n    <p>\\n      If the work takes longer, the first response can instead carry\\n      <code>TASK_STATE_SUBMITTED</code> or <code>TASK_STATE_WORKING</code>.\\n      The concierge can then get the task, subscribe to its stream, or receive\\n      authenticated push updates if the Agent Card advertises that capability.\\n    </p>\\n\\n    <h3 id=\\"11-4-approval-requires-another-turn\\">11.4 Approval requires another turn</h3>\\n    <pre><code class=\\"language-json\\">{\\n  \\"task\\": {\\n    \\"id\\": \\"task_456\\",\\n    \\"contextId\\": \\"purchase_8b1\\",\\n    \\"status\\": {\\n      \\"state\\": \\"TASK_STATE_INPUT_REQUIRED\\",\\n      \\"message\\": {\\n        \\"messageId\\": \\"msg-approval-1\\",\\n        \\"role\\": \\"ROLE_AGENT\\",\\n        \\"parts\\": [\\n          {\\"text\\": \\"Manager approval is required because the total exceeds $500.\\"},\\n          {\\n            \\"data\\": {\\n              \\"approvalForm\\": {\\n                \\"approver\\": \\"\\",\\n                \\"decision\\": \\"approve | reject\\"\\n              }\\n            }\\n          }\\n        ]\\n      }\\n    }\\n  }\\n}</code></pre>\\n\\n    <p>\\n      The follow-up Message includes the same <code>taskId</code> so the\\n      approval agent can continue the existing Task:\\n    </p>\\n\\n    <pre><code class=\\"language-json\\">{\\n  \\"message\\": {\\n    \\"messageId\\": \\"msg-approval-2\\",\\n    \\"taskId\\": \\"task_456\\",\\n    \\"contextId\\": \\"purchase_8b1\\",\\n    \\"role\\": \\"ROLE_USER\\",\\n    \\"parts\\": [\\n      {\\n        \\"data\\": {\\n          \\"approver\\": \\"manager-42\\",\\n          \\"decision\\": \\"approve\\"\\n        }\\n      }\\n    ]\\n  }\\n}</code></pre>\\n\\n    <details>\\n      <summary>Earlier illustrative payload shape and its 1.0 mapping</summary>\\n      <p>\\n        Early teaching examples often modeled task creation as a custom\\n        <code>POST /a2a/tasks</code> request with a top-level\\n        <code>skillId</code>, used the role <code>requester</code>, represented\\n        success as <code>succeeded</code>, and put\\n        <code>type</code>/<code>data</code> directly on an artifact:\\n      </p>\\n      <pre><code class=\\"language-json\\">{\\n  \\"skillId\\": \\"inventory.check\\",\\n  \\"message\\": {\\n    \\"role\\": \\"requester\\",\\n    \\"parts\\": [\\n      {\\"type\\": \\"data\\", \\"data\\": {\\"item\\": \\"keyboard\\", \\"quantity\\": 20}}\\n    ]\\n  }\\n}</code></pre>\\n      <pre><code class=\\"language-json\\">{\\n  \\"taskId\\": \\"task_123\\",\\n  \\"status\\": {\\"state\\": \\"succeeded\\"},\\n  \\"artifacts\\": [\\n    {\\n      \\"type\\": \\"data\\",\\n      \\"name\\": \\"inventory_quote\\",\\n      \\"data\\": {\\n        \\"item\\": \\"keyboard\\",\\n        \\"quantity\\": 20,\\n        \\"available\\": 18,\\n        \\"backorderEtaDays\\": 7,\\n        \\"unitPrice\\": 35.0,\\n        \\"currency\\": \\"USD\\",\\n        \\"estimatedTotal\\": 700.0\\n      }\\n    }\\n  ]\\n}</code></pre>\\n      <p>\\n        Those names are useful for a private REST API but are not the A2A 1.0\\n        contract. The current mapping is: send a\\n        <code>ROLE_USER</code> Message, use\\n        <code>TASK_STATE_COMPLETED</code> for success, and place data inside\\n        an Artifact\'s <code>parts</code> array.\\n      </p>\\n    </details>\\n\\n    <div class=\\"callout ok\\">\\n      Notice the separation: a status Message explains what the interaction\\n      needs next, while the final approval decision belongs in an explicit\\n      Artifact that downstream systems can validate and audit.\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"security\\">\\n    <h2 id=\\"12-security-and-authorization-boundaries\\">12) Security and authorization boundaries</h2>\\n\\n    <p>\\n      A2A intentionally relies on standard web security practices. That means:\\n    </p>\\n\\n    <div class=\\"cols\\">\\n      <div class=\\"card\\">\\n        <strong>Transport security</strong>\\n        <ul>\\n          <li>Use HTTPS for integrity and authenticity</li>\\n          <li>Verify the server certificate; consider mTLS between workloads</li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>Authentication</strong>\\n        <ul>\\n          <li>Bearer tokens obtained through OAuth/OIDC are common</li>\\n          <li>Service-to-service credentials for private deployments</li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>Authorization</strong>\\n        <ul>\\n          <li>Scopes/roles per skill (for example, <code>approval:write</code>)</li>\\n          <li>Don\u2019t let \u201cany agent\u201d call \u201cany skill\u201d</li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>File/URL safety</strong>\\n        <ul>\\n          <li>Validate file references to avoid SSRF</li>\\n          <li>Sanitize and validate user-provided data parts</li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Practical governance recommendation:</strong>\\n      Use allow-lists for which agents your concierge is permitted to hire,\\n      and limit which skills can be invoked based on policy.\\n    </div>\\n\\n    <h3 id=\\"12-1-discovery-describes-security-it-does-not-issue-credentials\\">12.1 Discovery describes security; it does not issue credentials</h3>\\n    <p>\\n      <code>securitySchemes</code> describes supported mechanisms and\\n      <code>securityRequirements</code> states which are required. The client\\n      obtains credentials through the appropriate out-of-band OAuth, workload,\\n      API-key, or certificate flow and transmits them through binding-specific\\n      headers or metadata on every request. The agent authenticates and\\n      authorizes each request; an Agent Card entry is not an access grant.\\n    </p>\\n\\n    <h3 id=\\"12-2-authentication-during-a-task-is-a-state-not-a-credential-envelope\\">12.2 Authentication during a task is a state, not a credential envelope</h3>\\n    <p>\\n      If later work needs additional authorization, the agent may transition\\n      the Task to <code>TASK_STATE_AUTH_REQUIRED</code> and explain the\\n      requirement in its status Message. Credentials remain out of ordinary\\n      Messages and Artifacts unless a separately negotiated extension defines\\n      a protected in-band mechanism.\\n    </p>\\n\\n    <h3 id=\\"12-3-push-callbacks-form-a-second-trust-boundary\\">12.3 Push callbacks form a second trust boundary</h3>\\n    <p>\\n      A push notification endpoint is an inbound API. Use a high-entropy\\n      callback URL or authenticated webhook token, validate the expected Task\\n      ID, reject unknown senders, apply replay/idempotency controls, and return\\n      a 2xx response only after durable acceptance. Delivery may be duplicated,\\n      so handlers must be idempotent.\\n    </p>\\n  </section>\\n\\n  <section id=\\"python\\">\\n    <h2 id=\\"13-mechanics-first-python-simulator-server-concierge-client\\">13) Mechanics-first Python simulator (server + concierge client)</h2>\\n\\n    <p>\\n      Below is the original minimal educational implementation, retained\\n      because writing the storage and routing mechanics by hand makes the\\n      lifecycle concrete. It publishes a card, accepts delegated work, tracks\\n      status, and returns an artifact.\\n    </p>\\n\\n    <div class=\\"tr-warn\\">\\n      <strong>Boundary of the example</strong>\\n      This FastAPI service is an <em>A2A-shaped simulator</em>, not a compliant\\n      A2A 1.0 server: it uses the private endpoint\\n      <code>POST /a2a/tasks</code> and omits binding-level version negotiation,\\n      streaming events, formal error mappings, and several required fields.\\n      Use an official or maintained A2A SDK for interoperability. The simulator\\n      exists to expose the moving parts before the SDK hides them.\\n    </div>\\n\\n    <h3 id=\\"13-1-specialist-agent-lifecycle-simulator-fastapi\\">13.1 Specialist agent lifecycle simulator (FastAPI)</h3>\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># inventory_agent.py</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">fastapi</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">FastAPI</span>, <span class=\\"typ\\">HTTPException</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">pydantic</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">BaseModel</span>\\n<span class=\\"kw\\">import</span> <span class=\\"typ\\">uuid</span>, <span class=\\"typ\\">time</span>\\n\\napp <span class=\\"op\\">=</span> <span class=\\"typ\\">FastAPI</span>(title<span class=\\"op\\">=</span><span class=\\"str\\">\\"Inventory Agent (A2A demo)\\"</span>)\\n\\n<span class=\\"com\\"># In-memory task store (demo only)</span>\\nTASKS <span class=\\"op\\">=</span> {}\\n\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">agent_card</span>():\\n    <span class=\\"kw\\">return</span> {\\n        <span class=\\"str\\">\\"name\\"</span>: <span class=\\"str\\">\\"Inventory Agent\\"</span>,\\n        <span class=\\"str\\">\\"description\\"</span>: <span class=\\"str\\">\\"Checks stock, price, and ETA for purchase requests.\\"</span>,\\n        <span class=\\"str\\">\\"supportedInterfaces\\"</span>: [{\\n            <span class=\\"str\\">\\"url\\"</span>: <span class=\\"str\\">\\"http://127.0.0.1:9101/a2a\\"</span>,\\n            <span class=\\"str\\">\\"protocolBinding\\"</span>: <span class=\\"str\\">\\"HTTP+JSON\\"</span>,\\n            <span class=\\"str\\">\\"protocolVersion\\"</span>: <span class=\\"str\\">\\"1.0\\"</span>,\\n        }],\\n        <span class=\\"str\\">\\"version\\"</span>: <span class=\\"str\\">\\"1.0.0\\"</span>,\\n        <span class=\\"str\\">\\"capabilities\\"</span>: {\\n            <span class=\\"str\\">\\"streaming\\"</span>: <span class=\\"kw\\">False</span>,\\n            <span class=\\"str\\">\\"pushNotifications\\"</span>: <span class=\\"kw\\">False</span>,\\n        },\\n        <span class=\\"str\\">\\"defaultInputModes\\"</span>: [<span class=\\"str\\">\\"text/plain\\"</span>, <span class=\\"str\\">\\"application/json\\"</span>],\\n        <span class=\\"str\\">\\"defaultOutputModes\\"</span>: [<span class=\\"str\\">\\"application/json\\"</span>],\\n        <span class=\\"str\\">\\"skills\\"</span>: [\\n            {\\n                <span class=\\"str\\">\\"id\\"</span>: <span class=\\"str\\">\\"inventory.check\\"</span>,\\n                <span class=\\"str\\">\\"name\\"</span>: <span class=\\"str\\">\\"Inventory Check\\"</span>,\\n                <span class=\\"str\\">\\"description\\"</span>: <span class=\\"str\\">\\"Returns stock, price, ETA, and estimated total.\\"</span>,\\n                <span class=\\"str\\">\\"tags\\"</span>: [<span class=\\"str\\">\\"inventory\\"</span>, <span class=\\"str\\">\\"pricing\\"</span>, <span class=\\"str\\">\\"procurement\\"</span>],\\n                <span class=\\"str\\">\\"examples\\"</span>: [<span class=\\"str\\">\\"Check availability for 20 keyboards.\\"</span>],\\n            }\\n        ]\\n    }\\n\\n<span class=\\"com\\"># Well-known discovery document (demo path)</span>\\n@app.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"/.well-known/agent-card.json\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">get_agent_card</span>():\\n    <span class=\\"kw\\">return</span> agent_card()\\n\\n<span class=\\"kw\\">class</span> <span class=\\"typ\\">CreateTask</span>(<span class=\\"typ\\">BaseModel</span>):\\n    skillId: <span class=\\"typ\\">str</span>\\n    message: <span class=\\"typ\\">dict</span>\\n\\n@app.<span class=\\"fn\\">post</span>(<span class=\\"str\\">\\"/a2a/tasks\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">create_task</span>(body: <span class=\\"typ\\">CreateTask</span>):\\n    <span class=\\"kw\\">if</span> body.skillId <span class=\\"op\\">!=</span> <span class=\\"str\\">\\"inventory.check\\"</span>:\\n        <span class=\\"kw\\">raise</span> <span class=\\"typ\\">HTTPException</span>(status_code<span class=\\"op\\">=</span><span class=\\"num\\">400</span>, detail<span class=\\"op\\">=</span><span class=\\"str\\">\\"Unsupported skillId\\"</span>)\\n\\n    task_id <span class=\\"op\\">=</span> <span class=\\"str\\">f\\"task_{uuid.uuid4().hex[:8]}\\"</span>\\n\\n    <span class=\\"com\\"># Parse the structured data part if present</span>\\n    item <span class=\\"op\\">=</span> <span class=\\"str\\">\\"unknown\\"</span>\\n    qty <span class=\\"op\\">=</span> <span class=\\"num\\">1</span>\\n    <span class=\\"kw\\">for</span> part <span class=\\"kw\\">in</span> body.message.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"parts\\"</span>, []):\\n        <span class=\\"kw\\">if</span> <span class=\\"str\\">\\"data\\"</span> <span class=\\"kw\\">in</span> part:\\n            data <span class=\\"op\\">=</span> part.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"data\\"</span>, {})\\n            item <span class=\\"op\\">=</span> data.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"item\\"</span>, item)\\n            qty <span class=\\"op\\">=</span> data.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"quantity\\"</span>, qty)\\n\\n    <span class=\\"com\\"># Demo logic</span>\\n    available <span class=\\"op\\">=</span> <span class=\\"num\\">18</span> <span class=\\"kw\\">if</span> item.<span class=\\"fn\\">lower</span>() <span class=\\"op\\">==</span> <span class=\\"str\\">\\"keyboard\\"</span> <span class=\\"kw\\">else</span> <span class=\\"num\\">5</span>\\n    unit_price <span class=\\"op\\">=</span> <span class=\\"num\\">35.0</span> <span class=\\"kw\\">if</span> item.<span class=\\"fn\\">lower</span>() <span class=\\"op\\">==</span> <span class=\\"str\\">\\"keyboard\\"</span> <span class=\\"kw\\">else</span> <span class=\\"num\\">10.0</span>\\n    eta_days <span class=\\"op\\">=</span> <span class=\\"num\\">7</span> <span class=\\"kw\\">if</span> qty <span class=\\"op\\">&gt;</span> available <span class=\\"kw\\">else</span> <span class=\\"num\\">0</span>\\n    total <span class=\\"op\\">=</span> <span class=\\"kw\\">float</span>(qty) <span class=\\"op\\">*</span> unit_price\\n\\n    TASKS[task_id] <span class=\\"op\\">=</span> {\\n        <span class=\\"str\\">\\"id\\"</span>: task_id,\\n        <span class=\\"str\\">\\"contextId\\"</span>: <span class=\\"str\\">\\"demo-purchase\\"</span>,\\n        <span class=\\"str\\">\\"createdAt\\"</span>: time.<span class=\\"fn\\">time</span>(),\\n        <span class=\\"str\\">\\"status\\"</span>: {<span class=\\"str\\">\\"state\\"</span>: <span class=\\"str\\">\\"TASK_STATE_COMPLETED\\"</span>},\\n        <span class=\\"str\\">\\"artifacts\\"</span>: [{\\n            <span class=\\"str\\">\\"artifactId\\"</span>: <span class=\\"str\\">f\\"artifact_{uuid.uuid4().hex[:8]}\\"</span>,\\n            <span class=\\"str\\">\\"name\\"</span>: <span class=\\"str\\">\\"Inventory quote\\"</span>,\\n            <span class=\\"str\\">\\"parts\\"</span>: [{\\n                <span class=\\"str\\">\\"data\\"</span>: {\\n                    <span class=\\"str\\">\\"item\\"</span>: item,\\n                    <span class=\\"str\\">\\"quantity\\"</span>: qty,\\n                    <span class=\\"str\\">\\"available\\"</span>: available,\\n                    <span class=\\"str\\">\\"backorderEtaDays\\"</span>: eta_days,\\n                    <span class=\\"str\\">\\"unitPrice\\"</span>: unit_price,\\n                    <span class=\\"str\\">\\"currency\\"</span>: <span class=\\"str\\">\\"USD\\"</span>,\\n                    <span class=\\"str\\">\\"estimatedTotal\\"</span>: total,\\n                }\\n            }]\\n        }]\\n    }\\n\\n    <span class=\\"kw\\">return</span> TASKS[task_id]\\n\\n@app.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"/a2a/tasks/{task_id}\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">get_task</span>(task_id: <span class=\\"typ\\">str</span>):\\n    t <span class=\\"op\\">=</span> TASKS.<span class=\\"fn\\">get</span>(task_id)\\n    <span class=\\"kw\\">if</span> <span class=\\"kw\\">not</span> t:\\n        <span class=\\"kw\\">raise</span> <span class=\\"typ\\">HTTPException</span>(status_code<span class=\\"op\\">=</span><span class=\\"num\\">404</span>, detail<span class=\\"op\\">=</span><span class=\\"str\\">\\"Unknown task\\"</span>)\\n    <span class=\\"kw\\">return</span> t\\n\\n<span class=\\"com\\"># Run:</span>\\n<span class=\\"com\\">#   pip install fastapi uvicorn</span>\\n<span class=\\"com\\">#   uvicorn inventory_agent:app --port 9101</span></code></pre>\\n\\n    <h3 id=\\"13-2-concierge-client-discover-skills-create-a-task-read-artifact\\">13.2 Concierge client: discover skills, create a task, read artifact</h3>\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># concierge.py</span>\\n<span class=\\"kw\\">import</span> <span class=\\"typ\\">uuid</span>\\n<span class=\\"kw\\">import</span> <span class=\\"typ\\">requests</span>\\n\\nINVENTORY_BASE <span class=\\"op\\">=</span> <span class=\\"str\\">\\"http://127.0.0.1:9101\\"</span>\\n\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">discover_agent</span>(base: <span class=\\"typ\\">str</span>) <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">dict</span>:\\n    r <span class=\\"op\\">=</span> requests.<span class=\\"fn\\">get</span>(base <span class=\\"op\\">+</span> <span class=\\"str\\">\\"/.well-known/agent-card.json\\"</span>, timeout<span class=\\"op\\">=</span><span class=\\"num\\">5</span>)\\n    r.<span class=\\"fn\\">raise_for_status</span>()\\n    <span class=\\"kw\\">return</span> r.<span class=\\"fn\\">json</span>()\\n\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">create_inventory_task</span>(base: <span class=\\"typ\\">str</span>, item: <span class=\\"typ\\">str</span>, qty: <span class=\\"typ\\">int</span>) <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">dict</span>:\\n    payload <span class=\\"op\\">=</span> {\\n      <span class=\\"str\\">\\"skillId\\"</span>: <span class=\\"str\\">\\"inventory.check\\"</span>,\\n      <span class=\\"str\\">\\"message\\"</span>: {\\n        <span class=\\"str\\">\\"role\\"</span>: <span class=\\"str\\">\\"ROLE_USER\\"</span>,\\n        <span class=\\"str\\">\\"messageId\\"</span>: <span class=\\"str\\">f\\"msg_{uuid.uuid4().hex[:8]}\\"</span>,\\n        <span class=\\"str\\">\\"parts\\"</span>: [\\n          {<span class=\\"str\\">\\"text\\"</span>: <span class=\\"str\\">f\\"Check availability and pricing for {qty} {item}s.\\"</span>},\\n          {<span class=\\"str\\">\\"data\\"</span>: {<span class=\\"str\\">\\"item\\"</span>: item, <span class=\\"str\\">\\"quantity\\"</span>: qty}}\\n        ]\\n      }\\n    }\\n    r <span class=\\"op\\">=</span> requests.<span class=\\"fn\\">post</span>(base <span class=\\"op\\">+</span> <span class=\\"str\\">\\"/a2a/tasks\\"</span>, json<span class=\\"op\\">=</span>payload, timeout<span class=\\"op\\">=</span><span class=\\"num\\">10</span>)\\n    r.<span class=\\"fn\\">raise_for_status</span>()\\n    <span class=\\"kw\\">return</span> r.<span class=\\"fn\\">json</span>()\\n\\n<span class=\\"kw\\">if</span> __name__ <span class=\\"op\\">==</span> <span class=\\"str\\">\\"__main__\\"</span>:\\n    card <span class=\\"op\\">=</span> discover_agent(INVENTORY_BASE)\\n    <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"Discovered agent:\\"</span>, card[<span class=\\"str\\">\\"name\\"</span>], <span class=\\"str\\">\\"skills=\\"</span>, [s[<span class=\\"str\\">\\"id\\"</span>] <span class=\\"kw\\">for</span> s <span class=\\"kw\\">in</span> card[<span class=\\"str\\">\\"skills\\"</span>]])\\n\\n    task <span class=\\"op\\">=</span> create_inventory_task(INVENTORY_BASE, <span class=\\"str\\">\\"keyboard\\"</span>, <span class=\\"num\\">20</span>)\\n    <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"Task status:\\"</span>, task[<span class=\\"str\\">\\"status\\"</span>][<span class=\\"str\\">\\"state\\"</span>])\\n    artifact <span class=\\"op\\">=</span> task[<span class=\\"str\\">\\"artifacts\\"</span>][<span class=\\"num\\">0</span>][<span class=\\"str\\">\\"parts\\"</span>][<span class=\\"num\\">0</span>][<span class=\\"str\\">\\"data\\"</span>]\\n    <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"Quote artifact:\\"</span>, artifact)</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      Even in this simplified demo, you can see the A2A \u201cshape\u201d:\\n      discover an agent (AgentCard), pick a skill, create a task, receive an artifact.\\n      The next implementation increment is to add the approval agent and model\\n      <code>TASK_STATE_INPUT_REQUIRED</code> before completion.\\n    </div>\\n  </section>\\n\\n  <section id=\\"operational\\">\\n    <h2 id=\\"14-operational-checklist-retries-idempotency-observability\\">14) Operational checklist (retries, idempotency, observability)</h2>\\n\\n    <div class=\\"cols\\">\\n      <div class=\\"card\\">\\n        <strong>Idempotency</strong>\\n        <ul>\\n          <li>Task creation should be safe to retry (idempotency keys)</li>\\n          <li>Artifact writes should be append-only or versioned</li>\\n          <li>Use unique Message IDs and deduplicate webhook deliveries</li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>Retries + timeouts</strong>\\n        <ul>\\n          <li>Use bounded retries with jitter</li>\\n          <li>Different timeouts for: card fetch, create task, poll task</li>\\n          <li>Do not retry a non-idempotent operation without a stable key</li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>Observability</strong>\\n        <ul>\\n          <li>Trace IDs per task and propagate them across agents</li>\\n          <li>Log skill invoked, caller identity, status transitions</li>\\n          <li>Correlate <code>contextId</code>, <code>taskId</code>, and <code>messageId</code></li>\\n        </ul>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>Safety</strong>\\n        <ul>\\n          <li>Validate file references and URLs (SSRF defense)</li>\\n          <li>Keep AgentCards free of secrets</li>\\n          <li>Use allow-lists for which agents can be contacted</li>\\n          <li>Honor <code>A2A-Version</code>; reject unsupported versions explicitly</li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      The easiest multi-agent failures are \u201csilent failure\u201d and \u201cinfinite waiting.\u201d\\n      Always implement: (1) clear status transitions, (2) timeouts, (3) explicit failure artifacts.\\n    </div>\\n\\n    <h3 id=\\"14-1-concurrency-and-terminal-state-rules\\">14.1 Concurrency and terminal-state rules</h3>\\n    <p>\\n      Treat the Task store as a concurrent state machine. Use compare-and-set\\n      or a transactional version column so two workers cannot both advance the\\n      same Task from <code>WORKING</code> to conflicting outcomes. A terminal\\n      Task must not return to a non-terminal state. Cancellation is a request\\n      to stop: workers still need cooperative checks and resource cleanup.\\n    </p>\\n\\n    <h3 id=\\"14-2-cache-discovery-not-authorization-decisions\\">14.2 Cache discovery, not authorization decisions</h3>\\n    <p>\\n      Agent Cards change relatively slowly and should use normal HTTP caching\\n      with <code>Cache-Control</code>, <code>ETag</code>, and conditional\\n      requests. Cache the card, but authenticate and authorize each task\\n      operation independently. A cached declaration that a skill exists does\\n      not prove the current caller may invoke it.\\n    </p>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section>\\n    <h2 id=\\"summary-the-complete-mental-model\\">Summary: the complete mental model</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>AgentCard</strong> enables discovery: who the agent is, what it can do, how to call it.</li>\\n        <li><strong>Skills</strong> enable routing: choose the right specialist agent for a subtask.</li>\\n        <li><strong>Tasks</strong> enable long-running collaboration: statuses, multi-turn messages, and deliverable artifacts.</li>\\n        <li><strong>Messages/Parts</strong> enable structured, multi-modality communication.</li>\\n        <li><strong>Artifacts</strong> are explicit outputs that downstream automation can reliably consume.</li>\\n        <li><strong>Bindings</strong> change transport syntax, while the canonical Task/Message/Artifact model stays equivalent.</li>\\n        <li><strong>Version and security</strong> are explicit on the boundary; agent autonomy does not bypass enterprise controls.</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <h2 id=\\"official-reference\\">Official reference</h2>\\n  <p>\\n    Field names and lifecycle values in the normative examples follow the\\n    <a href=\\"https://a2a-protocol.org/latest/specification/\\">A2A 1.0 specification</a>.\\n    Use the schema or an SDK for generated models rather than maintaining\\n    duplicate hand-written protocol classes in production.\\n  </p>\\n\\n</div>"}'),c={title:"A2A 1.0: Agent Discovery, Delegation, and Long-Running Tasks",slug:"/part3-agent-protocols/05-a2a-protocol",description:"The previous chapters used MCP to expose tools and context to an AI host. A2A addresses the next boundary: one autonomous agent delegates work to another autonomous agent without depending on the other agent's interna...",sidebar_label:"5. A2A protocol 1.0",pagination_label:"5. A2A protocol 1.0",hide_title:!0,hide_table_of_contents:!0},l=void 0,d={},p=[];function u(n){return(0,t.jsx)(r.A,{content:i})}function h(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,t.jsx)(e,{...n,children:(0,t.jsx)(u,{...n})}):u()}}}]);